/* Transparent Academy brand discovery: a tap-only conversation.
 *
 * Reads surveys.json (generated by survey_definitions.py) and plays it as a
 * chat: the guide asks, the respondent taps a reply. Every question has at
 * most five options. Nothing is typed except an optional contact (a separate
 * endpoint) and one optional closing question of type "text" (the respondent's
 * own opinion, any language). All text is set with textContent, never innerHTML.
 *
 * Preview mode (window.__PREVIEW__, used for the shareable demo page) reads
 * the survey from window.__SURVEYS__ and never touches the network.
 */
(function () {
  'use strict';

  const NA = 'na';
  const PREVIEW = !!window.__PREVIEW__;
  const params = new URLSearchParams(location.search);
  let surveyId = params.get('s') || 'students';
  const respondent = (params.get('r') || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 12);
  const meta = document.querySelector('meta[name="survey-relay"]');
  const relay = ((meta && meta.content) || '').replace(/\/$/, '');
  // Free route: an Apps Script web app that writes to Google Sheets. It takes the path as ?path= and a
  // text/plain body (a plain request, so the browser sends no preflight).
  const endpointMeta = document.querySelector('meta[name="survey-endpoint"]');
  const endpoint = ((endpointMeta && endpointMeta.content) || '').trim();
  const root = document.getElementById('app');
  const reduceMotion = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
  const TYPING_MS = reduceMotion ? 100 : 280;

  let config = null;
  let survey = null;
  const lang = 'en';

  const state = {
    phase: 'welcome',   // welcome | chat
    mode: 'question',   // question | typing | sending | offer | contact | error | done
    round: 1,
    idx: 0,
    answers: {},
    transcript: [],     // {kind: 'guide' | 'you' | 'chapter', text, fresh}
    marks: {},          // qid -> transcript length after its prompt was shown
    lastChapter: null,
    subIds: {},
    deviceId: null,
    retryRound: 1,
    pending: [],        // current multi-pick selection
    takeQ: null,        // the open "Your take" box, when mode is 'take'
  };

  // The hidden field bots tend to fill. Humans never see or reach it.
  const honeypot = document.createElement('input');
  honeypot.type = 'text';
  honeypot.name = 'website';
  honeypot.className = 'hp';
  honeypot.tabIndex = -1;
  honeypot.autocomplete = 'off';
  honeypot.setAttribute('aria-hidden', 'true');
  document.body.append(honeypot);

  // ---------------------------------------------------------------- helpers

  function el(tag, props, ...kids) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(props || {})) {
      if (v === false || v == null) continue;
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;
      else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else if (v === true) node.setAttribute(k, '');
      else node.setAttribute(k, v);
    }
    for (const kid of kids.flat()) {
      if (kid == null || kid === false) continue;
      node.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
    }
    return node;
  }

  function t(key, vars) {
    let s = (config.ui[lang] && config.ui[lang][key]) || config.ui.en[key] || key;
    for (const [k, v] of Object.entries(vars || {})) s = s.replace('{' + k + '}', v);
    return s;
  }

  function put(...nodes) {
    nodes.flat().forEach((n) => { if (n != null && n !== false) root.append(n); });
  }

  function hashStr(s) {
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }

  function rng(seed) {
    let a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let x = Math.imul(a ^ (a >>> 15), 1 | a);
      x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
      return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
    };
  }

  // Same order for the same device, so Undo never reshuffles the options.
  function shuffled(list, key) {
    const r = rng(hashStr(key));
    const a = list.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(r() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function randomId() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    const bytes = new Uint8Array(16);
    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(bytes);
    else bytes.forEach((_, i) => { bytes[i] = Math.floor(Math.random() * 256); });
    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  }

  function loadDeviceId() {
    try {
      let id = localStorage.getItem('ta_device');
      if (!id) { id = randomId(); localStorage.setItem('ta_device', id); }
      return id;
    } catch (e) {
      return randomId();
    }
  }

  function subId(round) {
    if (!state.subIds[round]) state.subIds[round] = randomId();
    return state.subIds[round];
  }

  // ------------------------------------------------------------ survey logic

  function currentGroup() {
    if (!survey.group_question) return 'all';
    const g = state.answers[survey.group_question];
    return survey.groups.includes(g) ? g : null;
  }

  // Every question of the round, including the "Your take" boxes that follow a question.
  function allQuestionsFor(round) {
    return survey.questions.filter((q) => q.round === round && (!q.groups || q.groups.includes(currentGroup())));
  }

  // The steps a respondent counts: a "Your take" box rides along with its question.
  function questionsFor(round) {
    return allQuestionsFor(round).filter((q) => !q.follows);
  }

  function takeFor(q) {
    return survey.questions.find((x) => x.follows === q.id) || null;
  }

  function choices(q) {
    if (q.type === 'scale') return q.labels.map((label, i) => ({ id: i + 1, label: label }));
    return q.shuffle === false ? q.options : shuffled(q.options, state.deviceId + '|' + q.id);
  }

  function labelFor(q, value) {
    if (value === NA) return t('skipped');
    if (q.type === 'text') return value.length > 160 ? value.slice(0, 157) + '…' : value;
    if (q.type === 'scale') return q.labels[value - 1];
    const byId = (id) => {
      const o = q.options.find((x) => x.id === id) || {};
      return o.other ? 'Something else' : (o.label || id);
    };
    return Array.isArray(value) ? value.map(byId).join(', ') : byId(value);
  }

  function minutesFor(count) {
    return Math.max(1, Math.ceil((count * survey.seconds_per_question) / 60));
  }

  // ----------------------------------------------------------------- network

  async function post(path, body) {
    if (PREVIEW) return { ok: true };
    const res = endpoint
      ? await fetch(endpoint + '?path=' + encodeURIComponent(path), {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(body),
      })
      : await fetch(relay + path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
    let data = {};
    try { data = await res.json(); } catch (e) { /* not JSON */ }
    if (res.status === 409 || data.already) return { ok: true, already: true };
    if (!res.ok || !data.ok) throw new Error(data.error || 'HTTP ' + res.status);
    return data;
  }

  function payloadFor(round) {
    const answers = {};
    allQuestionsFor(round).forEach((q) => {
      if (state.answers[q.id] !== undefined) answers[q.id] = state.answers[q.id];
    });
    return {
      survey: survey.id, round: round, submission_id: subId(round), device_id: state.deviceId,
      lang: lang, respondent: respondent, group: currentGroup(), answers: answers, website: honeypot.value,
    };
  }

  // -------------------------------------------------------------------- flow

  function say(text) { state.transcript.push({ kind: 'guide', text: text, fresh: true }); }

  function askCurrent() {
    const q = questionsFor(state.round)[state.idx];
    if (q.chapter !== state.lastChapter) {
      state.transcript.push({ kind: 'chapter', text: q.chapter, fresh: true });
      const intro = survey.chapters[q.chapter];
      if (intro) say(intro);
      state.lastChapter = q.chapter;
    }
    say(q.text);
    if (q.hint) say(q.hint);   // the "Your own words" prompt of a closing question
    state.marks[q.id] = state.transcript.length;
    state.pending = [];
    state.mode = 'question';
  }

  function after(ms, fn) { setTimeout(fn, ms); }

  function advance() {
    const list = questionsFor(state.round);
    if (state.idx >= list.length - 1) { submitRound(state.round); return; }
    state.idx += 1;
    state.mode = 'typing';
    render();
    after(TYPING_MS, () => { askCurrent(); render(); });
  }

  function answer(q, value) {
    state.answers[q.id] = value;
    state.transcript.push({ kind: 'you', text: labelFor(q, value), fresh: true });
    if (q.follows) { state.takeQ = null; advance(); return; }   // the "Your take" box was answered or skipped
    const take = takeFor(q);
    if (take && value === take.when) {
      // "Something else?" was chosen: offer the optional written answer before moving on
      state.takeQ = take;
      state.mode = 'typing';
      render();
      after(TYPING_MS, () => { say(take.text); state.mode = 'take'; render(); });
      return;
    }
    advance();
  }

  function undo() {
    const list = questionsFor(state.round);
    if (state.mode === 'take') {   // back to the question whose written take is open
      const open = list[state.idx];
      state.transcript.length = state.marks[open.id];
      delete state.answers[open.id];
      state.takeQ = null;
      state.mode = 'question';
      render();
      return;
    }
    if (state.idx === 0) return;
    state.idx -= 1;
    const q = list[state.idx];
    state.transcript.length = state.marks[q.id];
    state.lastChapter = q.chapter;
    delete state.answers[q.id];
    const take = takeFor(q);
    if (take) delete state.answers[take.id];
    state.pending = [];
    state.mode = 'question';
    render();
  }

  async function submitRound(round) {
    state.mode = 'sending';
    state.retryRound = round;
    render();
    try {
      await post('/survey/submit', payloadFor(round));
    } catch (e) {
      say(t('error_body'));
      state.mode = 'error';
      render();
      return;
    }
    await new Promise((r) => after(TYPING_MS, r));
    if (round === 1 && survey.round2_offer) {
      say(t('offer_body', { m: minutesFor(questionsFor(2).length) }));
      state.mode = 'offer';
    } else if (round === 2) {
      const q = survey.questions.find((x) => x.on_yes === 'contact');
      if (q && state.answers[q.id] === 'yes') { say(t('contact_ask')); state.mode = 'contact'; }
      else finish();
    } else {
      finish();
    }
    render();
  }

  function finish() { say(t('done_body')); state.mode = 'done'; }

  function startChat() {
    state.phase = 'chat';
    state.round = 1; state.idx = 0; state.answers = {}; state.transcript = [];
    state.marks = {}; state.lastChapter = null; state.subIds = {}; state.takeQ = null;
    askCurrent();
    render();
  }

  function switchSurvey(id) {
    surveyId = id;
    survey = config.surveys[id];
    state.phase = 'welcome';
    render();
  }

  // ------------------------------------------------------------------ screens

  function renderHeader() {
    const list = questionsFor(state.round);
    const chapters = [];
    list.forEach((q) => { if (!chapters.includes(q.chapter)) chapters.push(q.chapter); });
    const cur = list[Math.min(state.idx, list.length - 1)];
    const ci = Math.max(0, chapters.indexOf(cur && cur.chapter));
    const pct = state.mode === 'question' || state.mode === 'typing' || state.mode === 'take'
      ? Math.round((state.idx / list.length) * 100) : 100;
    return el('div', { class: 'top' },
      el('div', { class: 'bar', role: 'progressbar', 'aria-valuemin': '0', 'aria-valuemax': '100',
        'aria-valuenow': String(pct) }, el('span', { style: 'width:' + pct + '%' })),
      el('div', { class: 'meta' },
        el('span', { text: t('progress', { i: Math.min(state.idx + 1, list.length), n: list.length }) }),
        el('span', { class: PREVIEW ? 'badge' : '', text: PREVIEW ? 'Preview' : (cur ? cur.chapter : '') })));
  }

  function renderWelcome() {
    const mk = (id, label) => el('button', { type: 'button', text: label, 'aria-pressed': String(surveyId === id),
      onclick: () => switchSurvey(id) });
    const h1 = el('h1', { text: survey.title, tabindex: '-1' });
    put(
      el('div', { class: 'top' }, el('div', { class: 'bar' }, el('span', { style: 'width:0%' }))),
      el('p', { class: 'brand', text: 'Transparent Academy' }),
      h1,
      el('p', { text: survey.intro }),
      (survey.welcome || []).map((line) => el('p', { class: 'welcome', text: line })),
      el('p', { class: 'muted', text: t(survey.dedupe_by_device ? 'meta' : 'meta_named',
        { n: questionsFor(1).length, m: minutesFor(questionsFor(1).length) }) }),
      el('ul', { class: 'consent' }, survey.consent.map((line) => el('li', { text: line }))),
      PREVIEW ? el('p', { class: 'preview', text: t('preview_note') }) : null,
      PREVIEW ? el('div', { class: 'switch' },
        Object.entries(config.surveys).map(([id, s]) => mk(id, s.label || s.title))) : null,
      el('p'),
      el('button', { type: 'button', class: 'btn primary start', text: t('start'), onclick: startChat }),
      el('p', { class: 'credit', text: t('credit') }),
    );
  }

  function bubbleRow(entry) {
    if (entry.kind === 'chapter') {
      return el('div', { class: 'chapter' + (entry.fresh ? ' fresh' : ''), role: 'separator' },
        el('span', { text: entry.text }));
    }
    const mine = entry.kind === 'you';
    return el('div', { class: 'row ' + (mine ? 'you' : 'guide') + (entry.fresh ? ' fresh' : '') },
      mine ? null : el('div', { class: 'avatar', 'aria-hidden': 'true', text: 'TA' }),
      el('div', { class: 'bubble', text: entry.text }));
  }

  function typingRow() {
    return el('div', { class: 'row guide', 'aria-label': '…' },
      el('div', { class: 'avatar', 'aria-hidden': 'true', text: 'TA' }),
      el('div', { class: 'bubble typing' }, el('i'), el('i'), el('i')));
  }

  function chip(label, icon, pressed, onclick) {
    return el('button', { type: 'button', class: 'chip', 'aria-pressed': String(!!pressed), onclick: onclick },
      icon ? el('span', { class: 'ico', text: icon, 'aria-hidden': 'true' }) : null,
      el('span', { text: label }));
  }

  function undoLink() {
    return state.idx > 0 || state.mode === 'take'
      ? el('button', { type: 'button', class: 'link', text: t('undo'), onclick: undo }) : null;
  }

  // The one typed answer. Any language: dir="auto" so right-to-left scripts work,
  // and no input filtering. The relay cleans and caps it.
  function textBlock(q) {
    const box = el('textarea', { rows: '4', maxlength: String(q.max_chars || 600), dir: 'auto',
      autocomplete: 'off', spellcheck: 'false', placeholder: t('text_placeholder'),
      'aria-label': q.text });
    const send = el('button', { type: 'button', class: 'btn primary', text: t('send'), disabled: true });
    box.addEventListener('input', () => { send.disabled = box.value.trim().length === 0; });
    // "na" is the skip token on the wire, so a person who really writes "na" gets a full stop added
    send.addEventListener('click', () => {
      const v = box.value.trim();
      if (v) answer(q, v.toLowerCase() === NA ? v + '.' : v);
    });
    return [el('div', { class: 'opinion' }, box),
      el('div', { class: 'actions' }, send,
        q.na ? el('button', { type: 'button', class: 'link', text: t('skip'), onclick: () => answer(q, NA) }) : null,
        undoLink())];
  }

  function questionBlock() {
    const q = state.mode === 'take' ? state.takeQ : questionsFor(state.round)[state.idx];
    if (q.type === 'text') return textBlock(q);
    const list = choices(q);
    const cards = !!q.cards;

    if (q.type !== 'multi') {
      const replies = el('div', { class: 'replies' + (cards ? ' cards' : '') },
        list.map((o) => chip(o.label, o.icon, state.answers[q.id] === o.id, () => answer(q, o.id))));
      return [replies,
        el('div', { class: 'actions' }, q.na ? el('button', { type: 'button', class: 'link', text: t('skip'),
          onclick: () => answer(q, NA) }) : null, undoLink())];
    }

    const sendBtn = el('button', { type: 'button', class: 'btn primary', text: t('send'), disabled: true });
    const hint = el('p', { class: 'hint', text: t('pick_up_to', { n: q.max }) });
    const buttons = list.map((o) => {
      const b = chip(o.label, o.icon, false, () => {
        const at = state.pending.indexOf(o.id);
        if (at >= 0) state.pending.splice(at, 1);
        else if (state.pending.length < q.max) state.pending.push(o.id);
        paint();
      });
      b.dataset.id = o.id;
      return b;
    });
    function paint() {
      buttons.forEach((b) => {
        const on = state.pending.includes(b.dataset.id);
        b.setAttribute('aria-pressed', String(on));
        b.setAttribute('aria-disabled', String(!on && state.pending.length >= q.max));
      });
      sendBtn.disabled = state.pending.length === 0;
    }
    sendBtn.addEventListener('click', () => { if (state.pending.length) answer(q, state.pending.slice()); });
    paint();
    return [hint, el('div', { class: 'replies' + (cards ? ' cards' : '') }, buttons),
      el('div', { class: 'actions' }, sendBtn,
        q.na ? el('button', { type: 'button', class: 'link', text: t('skip'), onclick: () => answer(q, NA) }) : null,
        undoLink())];
  }

  function offerBlock() {
    return el('div', { class: 'replies' },
      chip(t('offer_yes'), null, false, () => {
        state.transcript.push({ kind: 'you', text: t('offer_yes'), fresh: true });
        state.round = 2; state.idx = 0; state.mode = 'typing'; render();
        after(TYPING_MS, () => { askCurrent(); render(); });
      }),
      chip(t('offer_no'), null, false, () => { state.transcript.push({ kind: 'you', text: t('offer_no'), fresh: true });
        finish(); render(); }));
  }

  function contactBlock() {
    const input = el('input', { type: 'text', inputmode: 'email', autocomplete: 'off', maxlength: '120',
      placeholder: t('contact_placeholder'), 'aria-label': t('contact_placeholder') });
    const note = el('p', { class: 'error' });
    const send = el('button', { type: 'button', class: 'btn primary', text: t('contact_send') });
    send.addEventListener('click', async () => {
      const v = input.value.trim();
      const ok = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,200}\.[A-Za-z]{2,}$/.test(v)
        || /^\+?[0-9][0-9 -]{6,18}[0-9]$/.test(v);
      if (!ok) { note.textContent = t('contact_bad'); return; }
      send.disabled = true;
      try {
        await post('/survey/contact', { survey: survey.id, contact: v, website: honeypot.value });
        state.transcript.push({ kind: 'you', text: t('contact_thanks'), fresh: true });
        finish(); render();
      } catch (e) {
        send.disabled = false;
        note.textContent = t('error_body');
      }
    });
    return el('div', { class: 'contact' }, input, note,
      el('div', { class: 'actions', style: 'margin-left:0' }, send,
        el('button', { type: 'button', class: 'link', text: t('contact_skip'),
          onclick: () => { finish(); render(); } })));
  }

  function renderChat() {
    const block = {
      question: questionBlock,
      take: questionBlock,
      offer: offerBlock,
      contact: contactBlock,
      error: () => el('div', { class: 'replies' }, chip(t('retry'), null, false, () => submitRound(state.retryRound))),
      typing: typingRow,
      sending: typingRow,
      done: () => null,
    }[state.mode]();
    put(renderHeader(), el('div', { class: 'chat', 'aria-live': 'polite' },
      state.transcript.slice(-4).map(bubbleRow), Array.isArray(block) ? block : [block]));
    state.transcript.forEach((e) => { e.fresh = false; });
  }

  function render() {
    root.replaceChildren();
    if (state.phase === 'welcome') { renderWelcome(); window.scrollTo(0, 0); return; }
    renderChat();
    requestAnimationFrame(() => {
      window.scrollTo({ top: document.documentElement.scrollHeight, behavior: reduceMotion ? 'auto' : 'smooth' });
    });
  }

  // -------------------------------------------------------------------- boot

  async function boot() {
    state.deviceId = loadDeviceId();
    try {
      if (PREVIEW) {
        config = window.__SURVEYS__;
      } else {
        const res = await fetch((relay || '.') + '/surveys.json', { cache: 'no-store' });
        config = await res.json();
      }
    } catch (e) {
      root.textContent = 'Could not load the survey. Please try again later.';
      return;
    }
    survey = config.surveys[surveyId];
    if (!survey) { root.textContent = config.ui.en.unknown_survey; return; }
    document.title = survey.title + ' · Transparent Academy';
    render();
  }

  boot();
})();
